import React, { useState, ReactElement } from "react"
import { PlusCircleIcon } from "@heroicons/react/24/solid"
import FBRadioGroup from "../radio/FBRadioGroup"
import Tooltip from "../Tooltip"
import DependencyWarning from "./DependencyWarning"
import DependencyPossibility from "./DependencyPossibility"
import { getRandomId } from "../utils"
import { fieldClass, fieldLabelClass } from "../fieldLayout"

// checks whether an array corresponds to oneOf dependencies
function checkIfValueBasedDependency(
  dependents: Array<{
    children: Array<string>
    value?: any
  }>
) {
  let valueBased = true
  if (dependents && Array.isArray(dependents) && dependents.length > 0) {
    dependents.forEach((possibility) => {
      if (!possibility.value || !possibility.value.enum) {
        valueBased = false
      }
    })
  } else {
    valueBased = false
  }

  return valueBased
}

type DependencyParams = {
  [key: string]: any
  name?: string
  dependents?: Array<{
    children: Array<string>
    value?: any
  }>
  type?: string
  enum?: Array<string | number>
  neighborNames?: Array<string>
  schema?: any
}

export default function DependencyField({
  parameters,
  onChange,
}: {
  parameters: DependencyParams
  onChange: (newParams: DependencyParams) => void
}): ReactElement {
  const [elementId] = useState(getRandomId())
  const valueBased = checkIfValueBasedDependency(parameters.dependents || [])
  return (
    <div className={`form-dependency dependencyField ${fieldClass}`}>
      <div className={`${fieldLabelClass} flex items-center gap-2`}>
        Dependencies
        <Tooltip
          id={`${elementId}_dependent`}
          type="help"
          text="Control whether other form elements show based on this one"
        />
      </div>
      {!!parameters.dependents && parameters.dependents.length > 0 && (
        <React.Fragment>
          <FBRadioGroup
            defaultValue={valueBased ? "value" : "definition"}
            horizontal={false}
            options={[
              {
                value: "definition",
                label: "Any value",
              },
              {
                value: "value",
                label: (
                  <div className="flex items-center gap-2">
                    Specific value
                    <Tooltip
                      id={`${elementId}_valuebased`}
                      type="help"
                      text="Specify whether these elements should show based on this element's value"
                    />
                  </div>
                ),
              },
            ]}
            onChange={(selection) => {
              if (parameters.dependents) {
                const newDependents = [...parameters.dependents]
                if (selection === "definition") {
                  parameters.dependents.forEach((possibility, index) => {
                    newDependents[index] = {
                      ...possibility,
                      value: undefined,
                    }
                  })
                } else {
                  parameters.dependents.forEach((possibility, index) => {
                    newDependents[index] = {
                      ...possibility,
                      value: { enum: [] },
                    }
                  })
                }
                onChange({
                  ...parameters,
                  dependents: newDependents,
                })
              }
            }}
          />
        </React.Fragment>
      )}
      <DependencyWarning parameters={parameters} />
      <div className="form-dependency-conditions flex flex-col gap-4">
        {parameters.dependents
          ? parameters.dependents.map((possibility, index) => (
              <DependencyPossibility
                possibility={possibility}
                neighborNames={parameters.neighborNames || []}
                parentEnums={parameters.enum}
                parentType={parameters.type}
                parentName={parameters.name}
                parentSchema={parameters.schema}
                // @ts-ignore: suppress key error, can't change key assignment
                key={`${elementId}_possibility${index}`}
                onChange={(newPossibility: { children: Array<string>; value?: any }) => {
                  const newDependents = parameters.dependents ? [...parameters.dependents] : []
                  newDependents[index] = newPossibility
                  onChange({
                    ...parameters,
                    dependents: newDependents,
                  })
                }}
                onDelete={() => {
                  const newDependents = parameters.dependents ? [...parameters.dependents] : []
                  onChange({
                    ...parameters,
                    dependents: [
                      ...newDependents.slice(0, index),
                      ...newDependents.slice(index + 1),
                    ],
                  })
                }}
              />
            ))
          : ""}

        <span
          className="tooltip tooltip-right tooltip-info z-50 before:max-w-xs inline-flex self-start cursor-pointer"
          data-tip="Add another dependency relation linking this element and other form elements"
          id={`${elementId}_adddependency`}
        >
          <PlusCircleIcon
            className="h-8 w-8 stroke-secondary stroke-2 fill-base-100 hover:stroke-primary transition-colors mt-2"
            onClick={() => {
              const newDependents = parameters.dependents ? [...parameters.dependents] : []
              newDependents.push({
                children: [],
                value: valueBased ? { enum: [] } : undefined,
              })
              onChange({
                ...parameters,
                dependents: newDependents,
              })
            }}
          />
        </span>
      </div>
    </div>
  )
}
